CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$; CREATE TABLE public.payments (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, booking_id UUID, user_id UUID NOT NULL, amount NUMERIC NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', payment_method TEXT NOT NULL CHECK (payment_method IN ('qr_banking','e_wallet','visa','mastercard')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','failed','refunded')), transaction_reference TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role; ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can read own payments" ON public.payments FOR SELECT USING (auth.uid() = user_id); CREATE POLICY "Admins can read all payments" ON public.payments FOR SELECT USING (has_role(auth.uid(), 'admin'::app_role)); CREATE POLICY "Users can insert own payments" ON public.payments FOR INSERT WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can update own payments" ON public.payments FOR UPDATE USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE TRIGGER update_payments_updated_at BEFORE UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE INDEX idx_payments_booking_id ON public.payments(booking_id); CREATE INDEX idx_payments_user_id ON public.payments(user_id);